// Local prototype forum: one atomic record for posts and the current draft.
const forumTopics=['工具使用','Agent / Skill','内容写作','网站搭建','学习路线','知识管理','职业发展','社区交流'];
const forumSeed=[{"id": "sample-report", "title": "我用 AI 写社会实践报告拿了一等奖：让结论有凭据", "body": "把走访记录与问卷作为依据，约束 AI 的结论，并保留可追溯的材料。原帖附 Skill 教程。", "author": "妙染", "topic": "内容写作", "sample": true, "source": "https://novaisland.cn/community/p_205214eafbaf48199dbe", "tags": ["内容写作", "Agent / Skill"]}, {"id": "sample-buddy", "title": "WorkBuddy 没有 token 了，日常 AI 任务怎么安排？", "body": "知识库、任务和办公都依赖同一个工具，额度耗尽后如何继续使用？原帖讨论工具额度与使用情况。", "author": "Endless", "topic": "工具使用", "sample": true, "source": "https://novaisland.cn/community/p_4ac004a88fe8440c9532", "tags": ["工具使用", "知识管理"]}, {"id": "sample-goals", "title": "把上百个准大一的问题，整理成一个目标判断 Skill", "body": "将“值得吗”“有必要吗”等困惑转换成明确目标与可执行的下一步。", "author": "化我", "topic": "Agent / Skill", "sample": true, "source": "https://novaisland.cn/community/p_7a23e848807f4d47a812", "tags": ["Agent / Skill", "学习路线"]}, {"id": "sample-career", "title": "求职复盘笔记", "body": "从城市、行业与岗位选择开始，复盘职业素养、资源积累和个人竞争力。", "author": "遇见韶华", "topic": "职业发展", "sample": true, "source": "https://novaisland.cn/community/p_bcbc945738e944078dd7", "tags": ["职业发展", "学习路线"]}, {"id": "sample-site", "title": "如何构建个人网页与学术博客：GitHub Pages 静态部署", "body": "用个人主页展示作品、记录学习与积累知识。原帖提供网站搭建思路与教程。", "author": "ASK", "topic": "网站搭建", "sample": true, "source": "https://novaisland.cn/community/p_7b812e66e183448d9fe5", "tags": ["网站搭建", "知识管理"]}];
let forumState={posts:[],draft:null},forumStorageWarning='';
try{const saved=JSON.parse(localStorage.getItem('nova-forum-v1')||'null');if(saved&&Array.isArray(saved.posts)){forumState.posts=saved.posts.filter(p=>p&&typeof p.id==='string'&&typeof p.title==='string'&&typeof p.body==='string');if(saved.draft&&typeof saved.draft.title==='string'&&typeof saved.draft.body==='string')forumState.draft=saved.draft;}}catch{forumStorageWarning='浏览器暂时无法读取已保存的帖子。';}
function forumSave(next){try{localStorage.setItem('nova-forum-v1',JSON.stringify(next));forumState=next;return true}catch{notify('保存失败：浏览器存储不可用或空间不足，正文仍保留在编辑器中。');return false}}
function forumMeta(p){return `<div class="forum-meta"><span class="card-avatar">${escapeHtml((p.author||'Sage').slice(0,1))}</span><span>${escapeHtml(p.author||'Sage')}</span><span>${escapeHtml((p.tags?.length?p.tags:[p.topic]).join(' / '))}</span><span>${p.sample?'线上内容摘要':new Date(p.created).toLocaleDateString('zh-CN')}</span></div>`;}
function forumRow(p){
 const author=p.author||'Sage';
 const tags=(p.tags?.length?p.tags:[p.topic]).filter(Boolean);
 return `<article class="forum-row"><div class="forum-meta"><span class="card-avatar">${escapeHtml(author.slice(0,1))}</span><span>${escapeHtml(author)}</span></div><a href="#community?post=${encodeURIComponent(p.id)}"><h2>${escapeHtml(p.title)}</h2><p>${escapeHtml(p.body)}</p></a><div class="forum-card-tags" aria-label="帖子标签">${tags.map(tag=>`<a href="#community?topic=${encodeURIComponent(tag)}">${escapeHtml(tag)}</a>`).join('')}</div></article>`;
}
function forumPage(){const params=route().params;if(params.has('compose'))return forumCompose();if(params.has('post'))return forumDetail(params.get('post'));const topics=params.getAll('topic').filter(t=>t!=='全部'),mine=params.get('mine')==='1',q=params.get('q')||'';const posts=[...forumState.posts,...(mine?[]:forumSeed)].filter(p=>(!topics.length||topics.some(t=>p.topic===t||(p.tags||[]).includes(t)))&&(!q||`${p.title} ${p.body}`.toLowerCase().includes(q.toLowerCase())));return `<section class="forum-page"><header class="forum-heading"><div><h1>论坛</h1><p>岛民的经验分享、学习记录与交流讨论。</p></div><a class="ds-button" href="#community?compose=1">＋ 发布帖子</a></header><div class="forum-layout"><div class="forum-feed-scroll" tabindex="0" role="region" aria-label="论坛帖子列表"><div class="forum-list-label"><span>${mine?'我的发布':'最新讨论'}</span><span>${posts.length} 篇帖子</span></div>${posts.length?posts.map(forumRow).join(''):`<div class="account-empty"><h2>${q?'没有找到相关讨论':mine?'还没有发布帖子':'这个分类还没有讨论'}</h2><p>${q?'换个关键词试试，或看看全部讨论。':'分享一个问题、一次实践或你的新作品。'}</p><a class="ds-button secondary" href="${q?'#community':'#community?compose=1'}">${q?'查看全部':'写第一篇帖子'}</a></div>`}</div><aside class="forum-aside"><section class="forum-tags-panel"><h2>标签</h2><nav class="forum-filters" aria-label="标签">${tagFilterButtons(forumTopics,topics,'topic')}<a href="#community?mine=1" ${mine?'aria-current="page"':''}>我的帖子</a></nav></section><a class="forum-draft-link" href="#drafts"><span>我的草稿</span><span>${forumState.draft?'1 篇待完成':'暂未保存'}</span></a><p class="forum-note">本地原型：新帖仅在当前浏览器可见。讨论摘要参考线上论坛，非实时同步。</p>${forumStorageWarning?`<p role="status">${forumStorageWarning}</p>`:''}</aside></div></section>`;}
function forumCompose(){const d=forumState.draft||{title:'',body:'',topic:forumTopics[0]};return `<section class="forum-editor"><a class="reader-back" href="#community">← 返回论坛</a><header class="home-heading"><h1>发布帖子</h1><p>一个好问题，一次新尝试，都值得分享。</p></header><form id="forum-compose"><fieldset class="forum-tag-picker"><legend>标签</legend>${forumTopics.map(t=>`<label><input type="checkbox" name="tags" value="${t}" ${(d.tags||[d.topic]).includes(t)?'checked':''}><span>${t}</span></label>`).join('')}</fieldset><label>标题<input class="ds-input" name="title" required maxlength="200" value="${escapeHtml(d.title)}" placeholder="用一句话说清楚你想讨论的事"></label><div class="forum-format-tools" role="toolbar" aria-label="正文排版"><button type="button" data-format="bold">加粗</button><button type="button" data-format="heading">小标题</button><button type="button" data-format="list">列表</button><button type="button" data-format="quote">引用</button><button type="button" data-preview-forum aria-pressed="false">预览正文</button></div><label id="forum-body-label">正文<textarea class="ds-input" name="body" required maxlength="50000" rows="12" placeholder="你的背景和目标是什么？尝试过哪些方法？期待得到什么帮助？">${escapeHtml(d.body)}</textarea></label><div id="forum-preview" class="forum-body" hidden></div><div class="forum-editor-status"><span id="draft-status" role="status">${forumState.draft?'已恢复本地草稿':'填写内容后自动保存草稿'}</span><span id="forum-word-count">${d.body.length} / 50000</span></div><p id="forum-error" role="alert" hidden></p><div class="forum-editor-actions"><button class="ds-button" type="submit">发布帖子</button><button class="ds-button secondary" type="button" data-save-forum>保存草稿</button><a href="#community">返回论坛</a></div><p class="forum-note">发布为本地演示，不会发送到线上社区。</p></form></section>`;}
function forumDetail(id){const p=[...forumState.posts,...forumSeed].find(p=>p.id===id);if(!p)return `${heading('帖子不存在')}<a href="#community" class="ds-button">返回论坛</a>`;return `<article class="forum-detail"><a class="reader-back" href="#community">← 返回论坛</a><h1>${escapeHtml(p.title)}</h1>${forumMeta(p)}<div class="forum-body">${forumBody(p.body)}</div>${p.source?`<a class="reader-back" href="${escapeHtml(p.source)}" target="_blank" rel="noopener">查看线上原帖</a><p class="forum-note">以上为原帖摘要，标题作了便于阅读的整理。</p>`:''}${forumActions(p)}<div class="forum-detail-footer"><span>${p.sample?'线上内容摘要':'已发布到本地原型'}</span>${!p.sample?`<button type="button" class="forum-withdraw" data-withdraw="${escapeHtml(p.id)}">撤回为草稿</button>`:''}<a href="#community?compose=1">我也来分享</a></div></article>`;}
function forumDrafts(){const d=forumState.draft;return `${heading('我的草稿','把还没写完的想法留在这里。')}${d?`<article class="forum-row"><span class="eyebrow">${escapeHtml(d.topic)}</span><a href="#community?compose=1"><h2>${escapeHtml(d.title||'未命名草稿')}</h2><p>${escapeHtml(d.body||'正文尚未填写')}</p><span class="forum-read">继续编辑</span></a></article>`:`<div class="account-empty"><h2>还没有保存的草稿</h2><p>写帖时会自动保存，可随时回来继续。</p><a class="ds-button" href="#community?compose=1">开始写帖</a></div>`}`;}
function forumDraftFrom(form){const d=new FormData(form);return {title:String(d.get('title')||''),body:String(d.get('body')||''),topic:String(d.getAll('tags')[0]||'社区交流'),tags:d.getAll('tags').map(String)}}
function saveForumDraft(form){const draft=forumDraftFrom(form);const ok=forumSave({...forumState,draft:draft.title.trim()||draft.body.trim()?draft:null});document.querySelector('#draft-status').textContent=ok?'草稿已保存到当前浏览器':'草稿未保存，请保留当前页面';document.querySelector('#forum-word-count').textContent=draft.body.length+' / 50000';return ok;}
document.addEventListener('input',e=>{if(e.target.closest('#forum-compose'))saveForumDraft(e.target.form)});
document.addEventListener('click',e=>{if(e.target.closest('[data-save-forum]')&&saveForumDraft(document.querySelector('#forum-compose')))notify('草稿已保存');});
document.addEventListener('submit',e=>{if(e.target.id!=='forum-compose')return;e.preventDefault();const draft=forumDraftFrom(e.target);const title=draft.title.trim(),body=draft.body.trim();if(!title||!body){const error=document.querySelector('#forum-error');error.hidden=false;error.textContent='标题和正文不能只包含空格。';return}const post={id:crypto.randomUUID(),title,body,topic:draft.topic,tags:draft.tags,author:'Sage',created:Date.now()};if(forumSave({posts:[post,...forumState.posts],draft:null})){location.hash='community?post='+post.id;notify('帖子已发布到本地原型')}});

function forumBody(text){return escapeHtml(text).split('\n').map(line=>line.startsWith('## ')?'<h2>'+line.slice(3)+'</h2>':line.startsWith('&gt; ')?'<blockquote>'+line.slice(5)+'</blockquote>':line.startsWith('- ')?'<div>• '+line.slice(2)+'</div>':line.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')).join('\n');}
document.addEventListener('click',e=>{const button=e.target.closest('[data-format]');if(button){const input=document.querySelector('#forum-compose textarea'),start=input.selectionStart,end=input.selectionEnd,selection=input.value.slice(start,end);const snippets={bold:'**'+(selection||'重点内容')+'**',heading:'\n## '+(selection||'小标题')+'\n',list:'\n- '+(selection||'列表项目')+'\n',quote:'\n> '+(selection||'引用内容')+'\n'};input.setRangeText(snippets[button.dataset.format],start,end,'select');input.focus();saveForumDraft(input.form)}const preview=e.target.closest('[data-preview-forum]');if(preview){const opened=preview.getAttribute('aria-pressed')!=='true';preview.setAttribute('aria-pressed',String(opened));preview.textContent=opened?'继续编辑':'预览正文';document.querySelector('#forum-body-label').hidden=opened;const box=document.querySelector('#forum-preview');box.hidden=!opened;box.innerHTML=forumBody(document.querySelector('#forum-compose textarea').value)||'正文还没有内容。'}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-withdraw]');if(!button)return;if(forumState.draft){notify('已有未完成草稿，请先发布或清空草稿再撤回。');return}const post=forumState.posts.find(p=>p.id===button.dataset.withdraw);if(post&&forumSave({posts:forumState.posts.filter(p=>p.id!==post.id),draft:{title:post.title,body:post.body,topic:post.topic,tags:post.tags||[post.topic]}})){location.hash='community?compose=1';notify('已撤回为草稿，内容完整保留')}});

// Per-browser reactions are separate from post/draft storage.
let forumReactions={};
try{const saved=JSON.parse(localStorage.getItem('nova-forum-reactions-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))forumReactions=saved}catch{}
function forumActions(p){const state=forumReactions[p.id]||{};const icon=path=>`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;return `<div class="forum-actions" aria-label="帖子操作"><button type="button" data-forum-action="liked" data-post-id="${escapeHtml(p.id)}" aria-pressed="${!!state.liked}">${icon('<path d="M7 10v11H3V10h4Zm0 0 5-8c3 0 2 5 1 7h6a2 2 0 0 1 2 2l-2 8a2 2 0 0 1-2 2H7"/>')}<span>${state.liked?'已点赞':'点赞'}</span></button><button type="button" data-forum-action="saved" data-post-id="${escapeHtml(p.id)}" aria-pressed="${!!state.saved}">${icon('<path d="M6 3h12v18l-6-4-6 4V3Z"/>')}<span>${state.saved?'已收藏':'收藏'}</span></button><button type="button" data-forum-action="share" data-post-id="${escapeHtml(p.id)}">${icon('<path d="M12 16V3m-4 4 4-4 4 4M5 12v9h14v-9"/>')}<span>分享</span></button></div>`}
function forumSaved(){const posts=[...forumState.posts,...forumSeed].filter(p=>forumReactions[p.id]?.saved);return `${heading('我的收藏','把值得再看的内容留在这里。')}${posts.length?posts.map(p=>`<article class="forum-row">${forumMeta(p)}<a href="#community?post=${encodeURIComponent(p.id)}"><h2>${escapeHtml(p.title)}</h2><p>${escapeHtml(p.body)}</p><span class="forum-read">查看帖子</span></a></article>`).join(''):accountEmpty('','还没有收藏内容','收藏的论坛帖子会显示在这里。','#community','浏览论坛')}`}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-forum-action]');if(!button)return;const id=button.dataset.postId,action=button.dataset.forumAction;const post=[...forumState.posts,...forumSeed].find(p=>p.id===id);if(!post)return;if(action==='share'){const url=new URL(location.href);url.hash='community?post='+encodeURIComponent(id);try{await navigator.clipboard.writeText(url.href);notify('帖子链接已复制')}catch{window.prompt('复制帖子链接',url.href)}return}const previous=forumReactions[id]||{};const next={...forumReactions,[id]:{...previous,[action]:!previous[action]}};try{localStorage.setItem('nova-forum-reactions-v1',JSON.stringify(next));forumReactions=next;button.closest('.forum-actions').outerHTML=forumActions(post);const replacement=document.querySelector(`[data-forum-action="${action}"]`);replacement?.focus();notify(action==='saved'?(next[id].saved?'已收藏，可在「我的收藏」查看':'已取消收藏'):(next[id].liked?'已点赞':'已取消点赞'))}catch{notify('保存失败，请检查浏览器存储是否可用。')}});

function tagFilterButtons(options,selected,key){return ['全部',...options].map(t=>`<button type="button" data-filter-tag="${escapeHtml(t)}" data-filter-key="${key}" aria-pressed="${t==='全部'?!selected.length:selected.includes(t)}">${escapeHtml(t)}</button>`).join('');}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-filter-tag]');if(!button)return;
 const {page,params}=route(),key=button.dataset.filterKey,tag=button.dataset.filterTag;
 let selected=params.getAll(key).filter(t=>t!=='全部');
 selected=tag==='全部'?[]:selected.includes(tag)?selected.filter(t=>t!==tag):[...selected,tag];
 params.delete(key);selected.forEach(t=>params.append(key,t));
 const query=params.toString();location.hash=page+(query?'?'+query:'');
});
